import { GetStakeResponse, GetWithdrawableStakeResponse, TxHashResponse } from "../types/schema/stake.js";
import { prepareRequestHeaders } from "../utils/headers.js";
import { http } from "../utils/http.js";
const STAKE_ENDPOINT = 'stake';
/**
 * Raw HTTP calls for the `/stake` endpoint.
 */
export async function getStake(requestOptions) {
  const response = await http(requestOptions, {
    method: 'get',
    responseType: 'json',
    url: STAKE_ENDPOINT
  });
  return GetStakeResponse.parse(response.data).stakedAmount;
}
export async function getWithdrawableStake(requestOptions) {
  const response = await http(requestOptions, {
    method: 'get',
    responseType: 'json',
    url: `${STAKE_ENDPOINT}/withdrawable`
  });
  return GetWithdrawableStakeResponse.parse(response.data).withdrawableAmount;
}
export async function depositStake(requestOptions, amountString, options) {
  const response = await http(requestOptions, {
    method: 'post',
    responseType: 'json',
    url: `${STAKE_ENDPOINT}/${amountString}`,
    headers: prepareRequestHeaders(null, options)
  });
  return TxHashResponse.parse(response.data).txHash;
}
export async function withdrawSurplusStake(requestOptions) {
  const response = await http(requestOptions, {
    method: 'delete',
    responseType: 'json',
    url: `${STAKE_ENDPOINT}/withdrawable`
  });
  return TxHashResponse.parse(response.data).txHash;
}
export async function migrateStake(requestOptions) {
  const response = await http(requestOptions, {
    method: 'delete',
    responseType: 'json',
    url: STAKE_ENDPOINT
  });
  return TxHashResponse.parse(response.data).txHash;
}